script:
(function () {
  'use strict';
  // Roth IRA conversion followed by retirement withdrawals: lifetime after-tax spending and what is
  // left for heirs, with and without converting.
  //   Conversion (start of 2026): taxable part = amount x (1 - basis / total IRA balances) (pro rata);
  //     federal tax = tax(income + taxable part) - tax(income) on the 2026 brackets; state = flat rate.
  //     Paid from savings: in the keep case that cash is invested in a taxable account instead.
  //     Paid from the IRA: the tax (and, under 59 1/2, the 10% additional tax on the taxable share of
  //     it) is not converted.
  //   Each year from your current age to the plan age (start of year, then growth):
  //     RMD (from the RMD age) = traditional balance / Uniform Lifetime factor; after tax = RMD less
  //     tax at the withdrawal rate on its non-basis share. Spending need = spending x (1 + increase)^k.
  //     Unspent RMD goes to the taxable account; any shortfall is met from the taxable account, then
  //     the traditional IRA (grossed up for tax), then the Roth IRA. Balances grow at the pre- or
  //     post-withdrawal return; the taxable account at that return x (1 - tax rate on returns).
  //   Legacy = traditional x (1 - heirs' rate on its non-basis part) + Roth + taxable account.
  // Checked in Node (fake DOM, whole script, tests/rcd.test.js): single, $50,000 income + $100,000
  //   conversion -> $22,846 federal ($400 at 12% + $55,300 at 22% + $44,300 at 24%); $40,000 basis in $400,000 ->
  //   $90,000 taxable; first RMD at 75 (born 1966) of an untouched $300,000 at 0% = $12,195 (/ 24.6);
  //   converting $40,000 inside the 22% band with 0% returns and 22% withdrawal and heirs' rates -> convert
  //   and keep give identical spending and legacy, whether the tax is paid from the IRA or from savings
  //   (untaxed side account): the textbook equal-rate result; age 80 -> the 2026 RMD is taken from the
  //   full balance before converting.
  //
  // ---- 2026 TAX FIGURES (tax year 2026) ------------------------------------------------------------
  // Brackets: IRS Rev. Proc. 2025-32, section 4.01 (as amended by P.L. 119-21); rates 10-37%.
  var TAX_YEAR = 2026;
  var BRACKETS = {
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var EARLY_TAX = 0.10, EARLY_AGE = 59.5; // IRC 72(t)
  // RMDs: Uniform Lifetime Table, IRS Pub. 590-B (2025) Appendix B Table III. Start age (SECURE 2.0
  // Act sec. 107): 72 if born 1950 or earlier, 73 if born 1951-1959, 75 if born 1960 or later.
  var UNIFORM_TABLE = {
    72: 27.4, 73: 26.5, 74: 25.5, 75: 24.6, 76: 23.7, 77: 22.9, 78: 22.0, 79: 21.1, 80: 20.2,
    81: 19.4, 82: 18.5, 83: 17.7, 84: 16.8, 85: 16.0, 86: 15.2, 87: 14.4, 88: 13.7, 89: 12.9,
    90: 12.2, 91: 11.5, 92: 10.8, 93: 10.1, 94: 9.5, 95: 8.9, 96: 8.4, 97: 7.8, 98: 7.3,
    99: 6.8, 100: 6.4, 101: 6.0, 102: 5.6, 103: 5.2, 104: 4.9, 105: 4.6, 106: 4.3, 107: 4.1,
    108: 3.9, 109: 3.7, 110: 3.5, 111: 3.4, 112: 3.3, 113: 3.1, 114: 3.0, 115: 2.9, 116: 2.8,
    117: 2.7, 118: 2.5, 119: 2.3, 120: 2.0
  };
  // ------------------------------------------------------------------------------------------------

  function tax(income, status) {
    var b = BRACKETS[status], t = 0, lower = 0;
    for (var k = 0; k < RATES.length; k++) {
      var upper = k < b.length ? b[k] : Infinity;
      if (income > lower) t += (Math.min(income, upper) - lower) * RATES[k];
      lower = upper;
    }
    return t;
  }
  function topRate(income, status) {
    var b = BRACKETS[status];
    for (var k = 0; k < b.length; k++) if (income <= b[k]) return RATES[k];
    return RATES[RATES.length - 1];
  }
  function rmdStartAge(birthYear) { return birthYear <= 1950 ? 72 : birthYear <= 1959 ? 73 : 75; }

  function conversionTax(p) {
    var taxable = p.balance > 0 ? p.amount * (1 - p.basis / p.balance) : 0;
    var fed = tax(p.income + taxable, p.status) - tax(p.income, p.status), state = taxable * p.stateRate;
    var penalty = 0, reached = p.amount;
    if (p.fromIra) {
      if (p.age < EARLY_AGE) penalty = Math.min(fed + state, p.amount) * EARLY_TAX * (p.amount > 0 ? taxable / p.amount : 0);
      reached = Math.max(0, p.amount - fed - state - penalty);
    }
    return { taxable: taxable, fed: fed, state: state, penalty: penalty, total: fed + state + penalty, reached: reached };
  }

  // One path. convert: bool; c: conversion result.
  function simulate(p, convert, c) {
    var trad = p.balance, basis = p.basis, roth = 0, side = 0, spent = 0, wdTax = 0, runOut = null, firstRmd = null, rows = [];
    var rmdAge = rmdStartAge(TAX_YEAR - p.age);
    var rmd0 = p.age >= rmdAge ? p.balance / UNIFORM_TABLE[Math.min(p.age, 120)] : 0; // 2026 RMD comes out before converting
    if (convert) {
      basis -= p.balance > 0 ? p.amount * p.basis / p.balance : 0;
      trad -= p.amount; roth = c.reached;
    } else if (!p.fromIra) {
      side = c.fed + c.state;
    }
    function takeTrad(gross) {
      if (gross <= 0 || trad <= 0) return 0;
      gross = Math.min(gross, trad);
      var frac = Math.min(1, Math.max(0, basis / trad)), t = gross * (1 - frac) * p.retireTax;
      basis -= gross * frac; trad -= gross; wdTax += t;
      return gross - t;
    }
    for (var a = p.age; a <= p.endAge; a++) {
      var need = a >= p.startAge ? p.spend * Math.pow(1 + p.growth, a - p.startAge) : 0;
      var rmd = a === p.age ? rmd0 : a >= rmdAge && trad > 0 ? trad / UNIFORM_TABLE[Math.min(a, 120)] : 0;
      if (rmd > 0 && firstRmd === null) firstRmd = { age: a, amount: rmd };
      var got = takeTrad(rmd), short = need;
      if (got >= need) { side += got - need; short = 0; } else { short = need - got; }
      if (short > 0) { var x = Math.min(side, short); side -= x; short -= x; }
      if (short > 0 && trad > 0) {
        var frac = Math.min(1, Math.max(0, basis / trad)), perGross = 1 - p.retireTax * (1 - frac);
        short -= takeTrad(perGross > 0 ? short / perGross : trad);
        if (short < 1e-6) short = 0;
      }
      if (short > 0) { var z = Math.min(roth, short); roth -= z; short -= z; }
      var used = need - short;
      spent += used;
      if (short > 0.5 && runOut === null) runOut = a;
      var rate = a < p.startAge ? p.ratePre : p.ratePost;
      trad *= 1 + rate; roth *= 1 + rate; side *= 1 + rate * (1 - p.investTax);
      if (trad < 0.005) trad = 0;
      rows.push({ age: a, spent: used, rmd: rmd, roth: roth, total: trad + roth + side });
    }
    var legacy = trad - Math.max(0, trad - basis) * p.heirTax + roth + side;
    return { spent: spent, legacy: legacy, wdTax: wdTax, runOut: runOut, firstRmd: firstRmd, rows: rows };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function pct(x) { return (Math.round(x * 1000) / 10) + '%'; }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }

  function update() {
    var balance = num('rcdBalance'), amount = num('rcdAmount'), income = num('rcdIncome'), age = num('rcdAge'),
        startAge = num('rcdStartAge'), endAge = num('rcdEndAge'), spend = num('rcdSpend'), growth = num('rcdGrowth'),
        ratePre = num('rcdRatePre'), ratePost = num('rcdRatePost'), retireTax = num('rcdRetireTax'), basis = num('rcdBasis'),
        stateRate = num('rcdState'), investTax = num('rcdInvestTax'), heirTax = num('rcdHeirTax'),
        status = document.getElementById('rcdStatus').value, fromIra = document.getElementById('rcdPayFrom').value === 'ira';
    var error = document.getElementById('rcdError');
    var bad = [balance, amount, income, age, startAge, endAge, spend, growth, ratePre, ratePost, retireTax, basis, stateRate,
               investTax, heirTax].some(isNaN) || balance <= 0 || amount <= 0 || amount > balance || basis < 0 || basis > balance ||
              income < 0 || [age, startAge, endAge].some(function (v) { return v !== Math.round(v); }) || age < 18 || age > 90 ||
              startAge < 60 || startAge < age || startAge > 100 || endAge < startAge || endAge <= age || endAge > 110 ||
              spend < 0 || growth < 0 || growth > 10 || ratePre < -20 || ratePre > 30 || ratePost < -20 || ratePost > 30 ||
              retireTax < 0 || retireTax > 70 || stateRate < 0 || stateRate > 20 || investTax < 0 || investTax > 70 ||
              heirTax < 0 || heirTax > 70;
    var rmdNow = !bad && age >= rmdStartAge(TAX_YEAR - age) ? balance / UNIFORM_TABLE[Math.min(age, 120)] : 0;
    if (!bad && rmdNow > 0 && amount > balance - rmdNow + 0.005) {
      error.hidden = false;
      error.textContent = 'Your 2026 RMD of ' + fmt(rmdNow) + ' must be taken first and can’t be converted, so convert at most ' +
                          fmt(balance - rmdNow) + '.';
      return;
    }
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter IRA balances above $0 with a conversion and basis no larger than them, whole-number ages ' +
                          '(current 18 to 90, withdrawals from 60 and not before your current age, plan age above both up to 110), ' +
                          'non-negative spending, an increase up to 10%, returns from -20 to 30% and tax rates up to 70% (state up to 20%).';
      return;
    }
    var p = { balance: balance, amount: amount, basis: basis, income: income, status: status, stateRate: stateRate / 100,
              fromIra: fromIra, age: age, startAge: startAge, endAge: endAge, spend: spend, growth: growth / 100,
              ratePre: ratePre / 100, ratePost: ratePost / 100, retireTax: retireTax / 100, investTax: investTax / 100,
              heirTax: heirTax / 100 };
    var c = conversionTax(p), conv = simulate(p, true, c), keep = simulate(p, false, c);
    var net = conv.spent + conv.legacy - keep.spent - keep.legacy;
    set('rcdNet', (Math.abs(net) < 0.5 ? '' : net > 0 ? '+' : '−') + fmt(Math.abs(net)));
    set('rcdConvTax', fmt(c.total));
    set('rcdSpendConv', fmt(conv.spent));
    set('rcdSpendKeep', fmt(keep.spent));
    set('rcdHorizon', 'Spending from age ' + startAge + ' through ' + endAge + ', plus what is left after tax at ' + endAge + '. Amounts are not adjusted for inflation.');
    set('rcdLegacy', fmt(conv.legacy) + ' / ' + fmt(keep.legacy));
    function lasts(s) { return s.runOut === null ? 'Past ' + endAge : 'Runs short at ' + s.runOut; }
    set('rcdLasts', lasts(conv) + ' / ' + lasts(keep));
    function first(s) { return s.firstRmd ? fmt(s.firstRmd.amount) + ' at ' + s.firstRmd.age : 'None'; }
    set('rcdFirstRmd', first(conv) + ' / ' + first(keep));
    set('rcdWdTax', fmt(conv.wdTax) + ' / ' + fmt(keep.wdTax));
    set('rcdTaxable', fmt(c.taxable));
    set('rcdFedState', fmt(c.fed) + ' / ' + fmt(c.state) + (c.penalty > 0 ? ' + ' + fmt(c.penalty) + ' early-withdrawal tax' : ''));
    var mb = topRate(income + 0.01, status), mt = topRate(income + c.taxable, status);
    set('rcdMarginal', pct(mb) + (mt !== mb ? ' rising to ' + pct(mt) : ''));
    set('rcdReached', fmt(c.reached));
    var early = document.getElementById('rcdEarly');
    early.hidden = !(age < EARLY_AGE);
    set('rcdEarly', 'You are under 59½: converted money taken out within 5 years of the conversion owes the 10% additional tax' +
        (fromIra ? ', and the tax withheld from the IRA already counts as an early distribution.' : '.'));
    var body = document.getElementById('rcdSchedule');
    body.textContent = '';
    conv.rows.forEach(function (x, i) {
      var k = keep.rows[i], tr = document.createElement('tr');
      [x.age, fmt(x.spent), fmt(k.spent), fmt(x.rmd), fmt(k.rmd), fmt(x.roth), fmt(x.total), fmt(k.total)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rcdForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
